package pricing

import (
	"fmt"
	"strconv"
	"strings"
)

// ParseCents turns a decimal price written as text into whole cents.
func ParseCents(s string) (int, error) {
	parts := strings.SplitN(strings.TrimSpace(s), ".", 2)
	whole, err := strconv.Atoi(parts[0])
	if err != nil {
		return 0, fmt.Errorf("bad price %q", s)
	}
	cents := whole * 100
	if len(parts) == 2 && len(parts[1]) > 0 {
		frac, err := strconv.Atoi(parts[1])
		if err != nil {
			return 0, fmt.Errorf("bad price %q", s)
		}
		// Pad or trim fractional part to exactly 2 digits.
		if len(parts[1]) == 1 {
			cents += frac * 10
		} else if len(parts[1]) >= 2 {
			cents += frac / (1 << (len(parts[1]) - 2))
		}
	}
	return cents, nil
}

