package norm

import "strings"

// Options controls Normalize behavior. A zero Options only trims ends.
type Options struct {
	Lower       bool // ASCII-lowercase letters (default false)
	Collapse    bool // collapse runs of whitespace into a single space (default false)
	StripPunct  bool // delete every ASCII punctuation byte (default false)
}

// Default returns options that lowercases, collapses whitespace, and trims.
func Default() Options {
	return Options{Lower: true, Collapse: true}
}

const punctSet = "!\"#$%&'()*+,-./:;<=>?@[\\]^_`{|}~"

// Normalize processes s according to opt, then always trims ends. When all
// three flags are true it is equivalent to the original single-argument version.
func Normalize(s string, opt Options) string {
	if opt.StripPunct {
		var out []byte
		for i := 0; i < len(s); i++ {
			c := s[i]
			if !isPunct(c) {
				out = append(out, c)
			}
		}
		s = string(out)
	}

	if opt.Collapse {
		s = strings.Join(strings.Fields(s), " ")
	}

	if opt.Lower {
		s = strings.ToLower(s)
	}

	// Always trim
	s = strings.TrimSpace(s)
	return s
}

func isPunct(c byte) bool {
	return strings.IndexByte(punctSet, c) >= 0
}

