package norm

import "strings"

// Options controls the behavior of Normalize.
type Options struct {
	Lower      bool // ASCII-lowercase words.
	Collapse   bool // Collapse runs of whitespace into a single space.
	StripPunct bool // Delete every ASCII punctuation byte.
}

// Default returns options equivalent to the original Normalize behavior:
// lowercase and collapse enabled, strip punctuation disabled.
func Default() Options {
	return Options{Lower: true, Collapse: true}
}

// Normalize applies the configured transformations and always trims the ends.
// A zero Options only trims.
func Normalize(s string, opt Options) string {
	if opt.StripPunct {
		var b strings.Builder
		for _, c := range s {
			if !isASCIIPunct(c) {
				b.WriteRune(c)
			}
		}
		s = b.String()
	}
	if opt.Collapse {
		s = strings.Join(strings.Fields(s), " ")
	}
	if opt.Lower {
		s = strings.ToLower(s)
	}
	return strings.TrimSpace(s)
}

func isASCIIPunct(r rune) bool {
	return r >= '!' && r <= '~'
}

