package norm

import "strings"

var asciiPunct = map[rune]bool{
	'!': true, '"': true, '#': true, '$': true, '%': true, '&': true, '\'': true, '(': true,
	')': true, '*': true, '+': true, ',': true, '-': true, '.': true, '/': true, ':': true,
	';': true, '<': true, '=': true, '>': true, '?': true, '@': true, '[': true, '\\': true,
	']': true, '^': true, '_': true, '`': true, '{': true, '|': true, '}': true, '~': true,
}

type Options struct {
	Lower      bool
	Collapse   bool
	StripPunct bool
}

func Default() Options {
	return Options{Lower: true, Collapse: true}
}

func Normalize(s string, opt Options) string {
	if opt.StripPunct {
		var buf []byte // but we work with runes...
		for _, r := range s {
			if !asciiPunct[r] {
