package norm

import "strings"

// Options controls how Normalize processes a string.
type Options struct {
	// Lower lowercases ASCII letters.
	Lower bool
	// Collapse replaces runs of whitespace with a single space.
	Collapse bool
	// StripPunct removes ASCII punctuation characters.
	StripPunct bool
}

// Default returns Options with Lower and Collapse true and StripPunct false,
// matching the original Normalize behaviour.
func Default() Options {
	return Options{Lower: true, Collapse: true}
}

// Normalize applies the configured operations on s and always trims the result.
// Operations are applied in order: StripPunct, then Collapse, then Lower.
func Normalize(s string, opt Options) string {
	if opt.StripPunct {
		var b []byte
		for i := 0; i < len(s); i++ {
			r := s[i]
			switch {
			case r >= '!': // ASCII puncts: 33..126
				// Check if r is one of the ASCII punctuation chars
				if isPunct(r) {
					continue
				}
			}
			b = append(b, r)
		}
		s = string(b)
	}
	if opt.Collapse {
		s = strings.Join(strings.Fields(s), " ")
	}
	if opt.Lower {
		s = strings.ToLower(s)
	}
	return strings.TrimSpace(s)
}

var punctMask = [128]byte{}

func init() {
	// Set bits for ASCII punctuation: !"#$%&'()*+,-./:;<=>?@[\\]^_`{|}~
	punctBytes := []byte("!\"#$%&'()*+,-./:;<=>?@[\\]^_`{|}~")
	for _, b := range punctBytes {
		punctMask[b] = 1
	}
}

func isPunct(r byte) bool {
	return r < len(punctMask) && punctMask[r] == 1
}

