import re
import sys

def main():
    args = sys.argv[1:]
    files = []
    min_count = None
    top_n = None
    exclude_words = set()

    # Parse options – they can appear anywhere and before/after FILE
    while args:
        token = args.pop(0)
        if token == '--min':
            if not args:
                print("tally: --min requires argument", file=sys.stderr)
                sys.exit(1)
            min_count = int(args.pop(0))
        elif token == '--top':
            if not args:
                print("tally: --top requires argument", file=sys.stderr)
                sys.exit(1)
            top_n = int(args.pop(0))
        elif token == '--exclude':
            if not args:
                print("tally: --exclude requires argument", file=sys.stderr)
                sys.exit(1)
            parts = args.pop(0).split(',')
            exclude_words.update(w.lower() for w in parts if w)
        elif token.startswith('--'):
            print(f"tally: unknown option: {token}", file=sys.stderr)
            sys.exit(1)
        else:
            files.append(token)

    if not files:
        print("tally: no file specified", file=sys.stderr)
        sys.exit(1)

    word_re = re.compile(r'[A-Za-z0-9_]+')
    counts = {}

    for filepath in files:
        if filepath == '-':
            fh = sys.stdin
        else:
            try:
                fh = open(filepath, 'r', encoding='utf-8', errors='replace')
            except OSError as e:
                print(f"tally: no such file: {filepath}", file=sys.stderr)
                sys.exit(2)

        with fh:
            text = fh.read()

        for m in word_re.finditer(text):
            word = m.group().lower()
            if word not in exclude_words:
                counts[word] = counts.get(word, 0) + 1

    # Sort: count descending, then word ascending
    sorted_words = sorted(counts.items(), key=lambda x: (-x[1], x[0]))

    # Apply --min
    if min_count is not None:
        sorted_words = [(w, c) for w, c in sorted_words if c >= min_count]

    # Apply --top
    if top_n is not None:
        sorted_words = sorted_words[:top_n]

    for word, count in sorted_words:
        print(f"{count} {word}")

if __name__ == '__main__':
    main()

