#!/usr/bin/env python3
"""tally: a command-line word counter."""

import re
import sys
from collections import Counter


def main():
    args = sys.argv[1:]

    # Parse options manually so FILE / '-' can appear anywhere
    min_count = None
    top_n = None
    exclude_words = set()
    file_arg = None

    i = 0
    while i < len(args):
        a = args[i]
        if a == "--min":
            i += 1
            min_count = int(args[i])
        elif a == "--top":
            i += 1
            top_n = int(args[i])
        elif a == "--exclude":
            i += 1
            for w in args[i].split(","):
                stripped = w.strip()
                if stripped:
                    exclude_words.add(stripped.lower())
        elif a == "-":
            file_arg = "-"
        elif a.startswith("-"):
            # unknown option, treat as file arg or just skip
            file_arg = a
        else:
            file_arg = a
        i += 1

    if file_arg is None:
        file_arg = "-"

    # Read input
    try:
        if file_arg == "-":
            fh = sys.stdin
            content = fh.read()
        else:
            fh = open(file_arg, "r")
            content = fh.read()
            fh.close()
    except (OSError, IOError):
        print(f"tally: no such file: {file_arg}", file=sys.stderr)
        sys.exit(2)

    # Extract words: maximal runs of [A-Za-z0-9_]
    raw_words = re.findall(r'[A-Za-z0-9_]+', content)
    words = [w.lower() for w in raw_words]

    counts = Counter(words)

    # Apply --exclude (case-insensitive — already lowercased)
    for w in list(counts):
        if w in exclude_words:
            del counts[w]

    # Apply --min
    if min_count is not None:
