    exclude_set = set()
    min_count = None
    top_n = None
    filename = None

    # Parse options before or after FILE
    i = 0
    while i < len(args):
        arg = args[i]
        if arg.startswith("--"):
            if arg == "--min":
                i += 1
                min_count = int(args[i])
            elif arg == "--top":
                i += 1
                top_n = int(args[i])
            elif arg == "--exclude":
                i += 1
                raw = args[i]
                exclude_set.update(w.lower() for w in raw.split(",") if w)
            else:
                print(f"tally: unknown option: {arg}", file=sys.stderr)
                sys.exit(1)
        else:
            filename = arg
        i += 1

    if filename is None:
        print("tally: no file specified", file=sys.stderr)
