package lexer

import (
	"fmt"
	"strings"
)

// Token represents a lexical token from the expression string.
type Token struct {
	Kind string // "num", "op", "lparen", "rparen"
	Text string
}

// Tokens splits an expression string into tokens.
// Returns an error if an unrecognized character is found.
func Tokens(s string) ([]Token, error) {
	var toks []Token
	s = strings.TrimSpace(s)
	if s == "" {
		return nil, nil
	}
	for len(s) > 0 {
		c := s[0]
		switch {
		case c >= '0' && c <= '9':
			i := 0
			for i < len(s) && s[i] >= '0' && s[i] <= '9' {
				i++
			}
			toks = append(toks, Token{Kind: "num", Text: s[:i]})
			s = s[i:]
		case c == '+' || c == '-' || c == '*' || c == '/':
			toks = append(toks, Token{Kind: "op", Text: string(c)})
			s = s[1:]
		case c == '(':
			toks = append(toks, Token{Kind: "lparen", Text: "("})
			s = s[1:]
		case c == ')':
			toks = append(toks, Token{Kind: "rparen", Text: ")"})
			s = s[1:]
		case c == ' ' || c == '\t' || c == '\n' || c == '\r':
			i := 0
			for i < len(s) && (s[i] == ' ' || s[i] == '\t' || s[i] == '\n' || s[i] == '\r') {
				i++
			}
			s = s[i:]
		default:
			return nil, fmt.Errorf("unexpected byte %q at position %d", c, 0)
		}
	}
	return toks, nil
}

