package lexer

import (
	"fmt"
)

// Token represents a lexical token from an expression string.
type Token struct {
	Kind string // "num", "op", "lparen", "rparen"
	Text string
}

// Tokens splits an expression string into tokens.
func Tokens(s string) ([]Token, error) {
	var toks []Token
	i := 0
	n := len(s)
	for i < n {
		ch := s[i]
		switch {
		case ch >= '0' && ch <= '9':
			j := i + 1
			for j < n && s[j] >= '0' && s[j] <= '9' {
				j++
			}
			toks = append(toks, Token{Kind: "num", Text: s[i:j]})
			i = j
		case ch == '+' || ch == '-' || ch == '*' || ch == '/':
			toks = append(toks, Token{Kind: "op", Text: s[i : i+1]})
			i++
		case ch == '(':
			toks = append(toks, Token{Kind: "lparen", Text: "("})
			i++
		case ch == ')':
			toks = append(toks, Token{Kind: "rparen", Text: ")"})
			i++
		case ch == ' ' || ch == '\t' || ch == '\n' || ch == '\r':
			i++
		default:
			return nil, fmt.Errorf("unexpected byte %q at position %d", s[i], i)
		}
	}
	if len(toks) == 0 {
		return nil, nil
	}
	return toks, nil
}

