// Node represents a parsed expression node.
type Node interface{}

// NumNode holds an integer literal value.
type NumNode struct {
	Value int
}

// BinOpNode holds a binary operation on two sub-expressions.
type BinOpNode struct {
	Left  Node
	Right Node
	Op    string
}

// Parse parses a slice of lexer tokens into an expression tree.
func Parse(toks []lexer.Token) (Node, error) {
	if toks == nil || len(toks) == 0 {
		return nil, fmt.Errorf("empty expression")
	}
	p := &parser{toks: toks, pos: 0}
	node, err := p.parseExpr()
	if err != nil {
		return nil, err
	}
	if p.pos < len(p.toks) {
		tok := p.toks[p.pos]
		return nil, fmt.Errorf("unexpected token %q (%s) at position %d", tok.Kind, tok.Text, p.pos)
	}
	return node, nil
}

type parser struct {
	toks []lexer.Token
	pos  int
}

func (p *parser) cur() lexer.Token {
	if p.pos < len(p.toks) {
		return p.toks[p.pos]
	}
	return lexer.Token{}
}

func (p *parser) advance() lexer.Token {
	t := p.cur()
	p.pos++
	return t
}

func (p *parser) peek() lexer.Token {
	return p.cur()
}

// parseExpr handles + and - (lowest precedence, left associative).
func (p *parser) parseExpr() (Node, error) {
	left, err := p.parseTerm()
	if err != nil {
		return nil, err
	}
	for {
		tok := p.peek()
		if tok.Kind != "op" || (tok.Text != "+" && tok.Text != "-") {
			break
		}
		op := p.advance().Text
		right, err := p.parseTerm()
		if err != nil {
			return nil, err
		}
		left = &BinOpNode{left, right, op}
	}
	return left, nil
}

// parseTerm handles * and / (higher precedence, left associative).
func (p *parser) parseTerm() (Node, error) {
	left, err := p.parseFactor()
	if err != nil {
		return nil, err
	}
	for {
		tok := p.peek()
		if tok.Kind != "op" || (tok.Text != "*" && tok.Text != "/") {
			break
		}
		op := p.advance().Text
		right, err := p.parseFactor()
		if err != nil {
			return nil, err
		}
		left = &BinOpNode{left, right, op}
	}
	return left, nil
}

// parseFactor handles literals, parenthesised expressions, and unary minus/plus.
func (p *parser) parseFactor() (Node, error) {
	tok := p.peek()
	switch tok.Kind {
