		if err != nil {
			return nil, err
		}
		tok = p.peek()
		if tok.Kind != "rparen" {
			if tok.Kind == "" {
				return nil, fmt.Errorf("unclosed parenthesis")
			}
			return nil, fmt.Errorf("expected ')' but got %q (%s)", tok.Kind, tok.Text)
		}
		p.advance() // consume ')'
		return expr, nil
