package eval

import (
	"fmt"

	"example.com/expr/parser"
)

// Eval evaluates a parsed expression tree and returns the result.
func Eval(n parser.Node) (int, error) {
	return evalNode(n)
}

func evalNode(n parser.Node) (int64, error) {
	switch node := n.(type) {
	case *parser.NumNode:
		return int64(node.Value), nil
	case *parser.BinOpNode:
		left, err := evalNode(node.Left)
		if err != nil {
			return 0, err
		}
		right, err := evalNode(node.Right)
		if err != nil {
			return 0, err
		}
		switch node.Op {
		case "+":
			return left + right, nil
		case "-":
			return left - right, nil
		case "*":
			return left * right, nil
		case "/":
			if right == 0 {
				return 0, fmt.Errorf("division by zero")
			}
			return left / right, nil
		default:
			return 0, fmt.Errorf("unknown operator %q", node.Op)
		}
	default:
		return 0, fmt.Errorf("unknown node type %T", n)
	}
}

