package main

import (
	"fmt"
	"os"

	"example.com/expr/eval"
	"example.com/expr/lexer"
	"example.com/expr/parser"
)

func main() {
	if len(os.Args) < 2 {
		fmt.Fprintln(os.Stderr, "usage: expr <expression>")
		os.Exit(1)
	}
	expr := os.Args[1]

	toks, err := lexer.Tokens(expr)
	if err != nil {
		fmt.Fprintf(os.Stderr, "tokenize error: %v\n", err)
		os.Exit(1)
	}

	node, err := parser.Parse(toks)
	if err != nil {
		fmt.Fprintf(os.Stderr, "parse error: %v\n", err)
		os.Exit(1)
	}

	result, err := eval.Eval(node)
	if err != nil {
		fmt.Fprintf(os.Stderr, "eval error: %v\n", err)
		os.Exit(1)
	}

	fmt.Println(result)
}

