package lexer

import "fmt"

// Token represents a lexical token from an integer expression.
type Token struct {
	Kind string // "num", "op", "lparen", "rparen"
	Text string // source text of the token
}

// Tokens splits the input string into tokens.
func Tokens(s string) ([]Token, error) {
	var toks []Token
	i := 0
	for i < len(s) {
		ch := s[i]
		switch {
		case ch == ' ' || ch == '\t' || ch == '\n' || ch == '\r':
			i++
		case (ch >= '0' && ch <= '9'):
			start := i
			for i < len(s) && s[i] >= '0' && s[i] <= '9' {
				i++
			}
			toks = append(toks, Token{"num", s[start:i]})
		case ch == '+' || ch == '-' || ch == '*' || ch == '/':
			toks = append(toks, Token{"op", string(ch)})
			i++
		case ch == '(':
			toks = append(toks, Token{"lparen", "("})
			i++
		case ch == ')':
			toks = append(toks, Token{"rparen", ")"})
			i++
		default:
			return nil, fmt.Errorf("unexpected character %q at position %d", ch, i)
		}
	}
	return toks, nil
}

