package parser

import (
	"fmt"

	"example.com/expr/lexer"
)

// Node represents an expression AST node.
type Node interface {
	nodeType()
}

// NumberNode is a literal integer value.
type NumberNode struct {
	Value int
}

func (*NumberNode) nodeType() {}

// BinaryOpNode is a binary operation with a left child, right child, and operator.
type BinaryOpNode struct {
	Left  Node
	Right Node
	Op    string
}

func (*BinaryOpNode) nodeType() {}

// Parse converts a list of tokens into an AST.
func Parse(toks []lexer.Token) (Node, error) {
	if len(toks) == 0 {
		return nil, fmt.Errorf("empty expression")
	}
	idx := 0
	var node Node
	var err error

	node, err = parsePrimary(toks, &idx)
	if err != nil {
		return nil, err
	}

	// Top-level +/- have lowest precedence, left-to-right.
	for idx < len(toks) && toks[idx].Kind == "op" &&
		(toks[idx].Text == "+" || toks[idx].Text == "-") {
		op := toks[idx].Text
		idx++
		if idx >= len(toks) {
			return nil, fmt.Errorf("missing operand after %q", op)
		}
		right, err := parsePrimary(toks, &idx)
		if err != nil {
			return nil, err
		}
		node = &BinaryOpNode{node, right, op}
	}

	if idx < len(toks) {
		return nil, fmt.Errorf("unexpected %q at position %d", toks[idx].Text, idx)
	}
	return node, nil
}

// parseExpression handles + and − at the given precedence level, left-to-right.
// Called recursively to support nesting inside parentheses.
func parseExpression(toks []lexer.Token, idx *int) (Node, error) {
	node, err := parseTerm(toks, idx)
	if err != nil {
		return nil, err
	}
	for *idx < len(toks) && toks[*idx].Kind == "op" &&
		(toks[*idx].Text == "+" || toks[*idx].Text == "-") {
		op := toks[*idx].Text
		*idx++
		if *idx >= len(toks) {
			return nil, fmt.Errorf("missing operand after %q", op)
		}
		right, err := parseTerm(toks, idx)
		if err != nil {
			return nil, err
		}
		node = &BinaryOpNode{node, right, op}
	}
	return node, nil
}

// parseTerm handles * and / at the given precedence level, left-to-right.
func parseTerm(toks []lexer.Token, idx *int) (Node, error) {
	node, err := parseFactor(toks, idx)
	if err != nil {
		return nil, err
	}
	for *idx < len(toks) && toks[*idx].Kind == "op" &&
		(toks[*idx].Text == "*" || toks[*idx].Text == "/") {
		op := toks[*idx].Text
		*idx++
		if *idx >= len(toks) {
			return nil, fmt.Errorf("missing operand after %q", op)
		}
		right, err := parseFactor(toks, idx)
		if err != nil {
			return nil, err
		}
		node = &BinaryOpNode{node, right, op}
	}
	return node, nil
}

// parseFactor handles numeric literals and parenthesised sub-expressions.
func parseFactor(toks []lexer.Token, idx *int) (Node, error) {
	if *idx >= len(toks) {
		return nil, fmt.Errorf("missing operand")
	}
	tok := toks[*idx]
	switch tok.Kind {
	case "num":
		*idx++
		var val int
		fmt.Sscanf(tok.Text, "%d", &val)
		return &NumberNode{Value: val}, nil
	case "lparen":
		*idx++
		node, err := parseExpression(toks, idx)
		if err != nil {
			return nil, err
		}
		if *idx >= len(toks) || toks[*idx].Kind != "rparen" {
			return nil, fmt.Errorf("unclosed parenthesis")
		}
		*idx++
		return node, nil
	default:
		return nil, fmt.Errorf("unexpected %q at position %d", tok.Text, *idx)
	}
}

