// Package parser provides an arithmetic expression parser with proper
// operator precedence and left-associativity.
package parser

import (
	"fmt"
	"strconv"

	"example.com/expr/lexer"
)

// Node represents a parsed expression node.
type Node interface {
	unexported()
}

// NumberNode holds an integer literal.
type NumberNode struct {
	Value int
}

func (NumberNode) unexported() {}

// BinaryExpr holds a binary operation with left/right operands and an operator.
type BinaryExpr struct {
	Left  Node
	Right Node
	Op    string
}

func (BinaryExpr) unexported() {}

// Parse consumes the token stream and builds an AST.
// Operator precedence: * / above + -, all left-associative.
// Parentheses group sub-expressions. Malformed input returns an error.
func Parse(toks []lexer.Token) (Node, error) {
	p := &parser{toks: toks, pos: 0}
	node, err := p.parseExpr()
	if err != nil {
		return nil, err
	}
	if p.pos < len(p.toks) {
		return nil, fmt.Errorf("unexpected token %q after expression", p.toks[p.pos].Text)
	}
	return node, nil
}

type parser struct {
	toks  []lexer.Token
	pos   int
	cur   lexer.Token
	hasCur bool
}

func (p *parser) advance() {
	p.pos++
	if p.pos < len(p.toks) {
		p.cur = p.toks[p.pos]
		p.hasCur = true
	} else {
		p.hasCur = false
	}
}

func (p *parser) expect(kind string) error {
	if !p.hasCur || p.cur.Kind != kind {
		if !p.hasCur {
			return fmt.Errorf("expected %q but reached end of input", kind)
		}
		return fmt.Errorf("expected %q but found %q (%q)", kind, p.cur.Text, p.cur.Kind)
	}
	p.advance()
	return nil
}

func (p *parser) parseExpr() (Node, error) {
	left, err := p.parseTerm()
	if err != nil {
		return nil, err
	}
	for p.hasCur && (p.cur.Kind == "op") {
		op := p.cur.Text
		if op != "+" && op != "-" {
			break
		}
		p.advance()
		right, err := p.parseTerm()
		if err != nil {
			return nil, err
		}
		left = BinaryExpr{Left: left, Right: right, Op: op}
	}
	return left, nil
}

func (p *parser) parseTerm() (Node, error) {
	left, err := p.parseFactor()
	if err != nil {
		return nil, err
	}
	for p.hasCur && p.cur.Kind == "op" {
		op := p.cur.Text
		if op != "*" && op != "/" {
			break
		}
		p.advance()
		right, err := p.parseFactor()
		if err != nil {
			return nil, err
		}
		left = BinaryExpr{Left: left, Right: right, Op: op}
	}
	return left, nil
}

func (p *parser) parseFactor() (Node, error) {
	if !p.hasCur {
		return nil, fmt.Errorf("unexpected end of input, expected operand")
	}

	switch p.cur.Kind {
	case "lparen":
		p.advance()
		node, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		if err := p.expect("rparen"); err != nil {
			return nil, err
		}
		return node, nil

	case "num":
		val, err := strconv.Atoi(p.cur.Text)
		if err != nil {
			return nil, fmt.Errorf("invalid number %q", p.cur.Text)
		}
		p.advance()
		return NumberNode{Value: val}, nil

	default:
		return nil, fmt.Errorf("unexpected token %q while parsing factor", p.cur.Text)
	}
}

