// Package eval evaluates a parsed expression tree into an integer result.
package eval

import (
	"fmt"

	"example.com/expr/parser"
)

// Eval evaluates the given parse tree and returns the integer result.
// Division by zero returns an error.
func Eval(n parser.Node) (int, error) {
	switch node := n.(type) {
	case parser.NumberNode:
		return node.Value, nil

	case parser.BinaryExpr:
		left, err := Eval(node.Left)
		if err != nil {
			return 0, err
		}
		right, err := Eval(node.Right)
		if err != nil {
			return 0, err
		}
		switch node.Op {
		case "+":
			return left + right, nil
		case "-":
			return left - right, nil
		case "*":
			return left * right, nil
		case "/":
			if right == 0 {
				return 0, fmt.Errorf("division by zero")
			}
			return left / right, nil
		default:
			return 0, fmt.Errorf("unknown operator %q", node.Op)
		}

	default:
		return 0, fmt.Errorf("unknown node type %T", n)
	}
}

