def main(path):
    with open(path, newline="") as f:
        rows = list(csv.reader(f))

    if not rows:
        return

    num_cols = max(len(r) for r in rows)

    widths = [0] * num_cols
    for row in rows:
        for i in range(min(len(row), num_cols)):
