package fetch

import "sync"

// Fetcher memoises the results of an expensive computation.
type Fetcher struct {
	mu     sync.RWMutex
	cache  map[string]int
	calls  int
	locks  map[string]*sync.Mutex
}

// New returns a Fetcher that computes missing values with f.
func New(f func(string) int) *Fetcher {
	return &Fetcher{cache: map[string]int{}, locks: map[string]*sync.Mutex{}}
}

// Get returns the value for k, computing it only the first time.
func (f *Fetcher) Get(k string) int {
	// Fast path: cached value read under RLock.
	f.mu.RLock()
	if v, ok := f.cache[k]; ok {
		f.mu.RUnlock()
		return v
	}
	f.mu.RUnlock()

	// Acquire per-key lock (or create it).
	f.mu.Lock()
	ml, ok := f.locks[k]
	if !ok {
		ml = &sync.Mutex{}
		f.locks[k] = ml
	}
	f.mu.Unlock()

	ml.Lock()
	defer ml.Unlock()

	// Double-check after acquiring the per-key lock.
	if v, ok := f.cache[k]; ok {
		return v
	}

	f.calls++
	v := f.compute(k)
	f.cache[k] = v
	return v
}

// Calls reports how many times compute has been called.
func (f *Fetcher) Calls() int {
	f.mu.Lock()
	defer f.mu.Unlock()
	return f.calls
}

// All returns the value for every key, fetching them concurrently.
func (f *Fetcher) All(keys []string) map[string]int {
	out := map[string]int{}
	var wg sync.WaitGroup
	for _, k := range keys {
		wg.Add(1)
		go func(k string) {
			defer wg.Done()
			out[k] = f.Get(k)
		}(k)
	}
	wg.Wait()
	return out
}

