package fetch

import (
	"sync"
)

// Fetcher memoises the results of an expensive computation.
type Fetcher struct {
	compute func(string) int
	cache   map[string]int
	calls   int
	mu      sync.RWMutex
	loads   map[string]*sync.Mutex
}

// New returns a Fetcher that computes missing values with f.
func New(f func(string) int) *Fetcher {
	return &Fetcher{compute: f, cache: map[string]int{}, loads: map[string]*sync.Mutex{}}
}

// Get returns the value for k, computing it only the first time.
func (f *Fetcher) Get(k string) int {
	f.mu.RLock()
	v, ok := f.cache[k]
	loading := f.loads[k]
	f.mu.RUnlock()

	if ok {
		return v
	}

	// Acquire the per-key lock; the first caller holds it across the full
	// compute and stores the result so subsequent callers resume waiting.
	f.mu.Lock()
	if loading == nil {
		loading = &sync.Mutex{}
		f.loads[k] = loading
	}
	f.mu.Unlock()

	loading.Lock() // serialises all goroutines for this key

	// Double-check after acquiring the per-key lock.
	f.mu.Lock()
	v, ok = f.cache[k]
	if !ok {
		f.calls++
		v = f.compute(k)
		f.cache[k] = v
	}
	f.mu.Unlock()

	loading.Unlock()
	return v
}

// Calls reports how many times compute has been called.
func (f *Fetcher) Calls() int {
	f.mu.Lock()
	defer f.mu.Unlock()
	return f.calls
}

// All returns the value for every key, fetching them concurrently.
func (f *Fetcher) All(keys []string) map[string]int {
	out := map[string]int{}
	var wg sync.WaitGroup
	for _, k := range keys {
		wg.Add(1)
		go func(k string) {
			defer wg.Done()
			out[k] = f.Get(k)
		}(k)
	}
	wg.Wait()
	return out
}

