package fetch

import "sync"

// Fetcher memoises the results of an expensive computation.
type Fetcher struct {
	compute func(string) int
	mu      sync.Mutex
	cache   map[string]int
	pending map[string]*sync.WaitGroup
	calls   int
}

// New returns a Fetcher that computes missing values with f.
func New(f func(string) int) *Fetcher {
	return &Fetcher{compute: f, cache: map[string]int{}, pending: map[string]*sync.WaitGroup{}}
}

// Get returns the value for k, computing it only the first time.
func (f *Fetcher) Get(k string) int {
	f.mu.Lock()
	if v, ok := f.cache[k]; ok {
		f.mu.Unlock()
		return v
	}
	if wg, ok := f.pending[k]; ok {
		f.mu.Unlock()
		wg.Wait()
		f.mu.Lock()
		v := f.cache[k]
		f.mu.Unlock()
		return v
	}
	wg := &sync.WaitGroup{}
	wg.Add(1)
	f.pending[k] = wg
	f.mu.Unlock()
	v := f.compute(k)
	f.mu.Lock()
	f.cache[k] = v
	f.calls++
	delete(f.pending, k)
	f.mu.Unlock()
	wg.Done()
	return v
}

// Calls reports how many times compute has been called.
func (f *Fetcher) Calls() int { return f.calls }

// All returns the value for every key, fetching them concurrently.
func (f *Fetcher) All(keys []string) map[string]int {
	out := map[string]int{}
	var mu sync.Mutex
	var wg sync.WaitGroup
	for _, k := range keys {
		wg.Add(1)
		go func(k string) {
			defer wg.Done()
			v := f.Get(k)
			mu.Lock()
			out[k] = v
			mu.Unlock()
		}(k)
	}
	wg.Wait()
	return out
}

