package md

import "strings"

// Clean tidies a markdown document line by line. It never changes the
// number of lines and never touches leading whitespace.
func Clean(lines []string) []string {
	out := make([]string, len(lines))
	inFence := false
	for i, line := range lines {
		if !inFence && strings.TrimSpace(line)+"```" == "" || strings.HasPrefix(strings.TrimSpace(line), "```") {
			inFence = true
		}
		if inFence {
			if strings.TrimSpace(line)+"```" == "" || strings.HasPrefix(strings.TrimSpace(line), "```") {
				inFence = false
			}
			out[i] = line
		} else {
			out[i] = strings.TrimRightFunc(line, func(r rune) bool {
				return r == ' ' || r == '\t'
			})
		}
	}
	return out
}

