package md

import "strings"

// Clean tidies a markdown document line by line. It never changes the
// number of lines and never touches leading whitespace.
func Clean(lines []string) []string {
	out := make([]string, len(lines))
	inCodeBlock := false
	for i, line := range lines {
		trimmed := strings.TrimSpace(line)
		if !inCodeBlock && strings.HasPrefix(trimmed, "```") {
			inCodeBlock = true
			out[i] = line
			continue
		}
		if inCodeBlock && strings.HasPrefix(trimmed, "```") {
			inCodeBlock = false
			out[i] = line
			continue
		}
		if inCodeBlock {
			out[i] = line
		} else {
			out[i] = trimTrailingWhitespace(line)
		}
	}
	return out
}

func trimTrailingWhitespace(s string) string {
	end := len(s)
	for end > 0 && (s[end-1] == ' ' || s[end-1] == '\t') {
		end--
	}
	return s[:end]
