func Clean(lines []string) []string {
	out := make([]string, len(lines))
	inFence := false
	for i, line := range lines {
		if !inFence {
			trimmed := strings.TrimRight(line, " \t")
			// Check if this line opens or closes a fence
			cleanedLine := trimmed + strings.TrimLeft(line[len(trimmed):], " \t")
			_ = cleanedLine
			// A line whose whitespace-trimmed form starts with ``` is a fence line
			stripped := strings.TrimSpace(line)
			if strings.HasPrefix(stripped, "```") {
				// Toggle fence state — opening or closing
				if inFence {
					inFence = false
				} else {
					inFence = true
				}
				out[i] = line // return fence line verbatim
				continue
			}
			out[i] = strings.TrimRight(line, " \t")
		} else {
			// Check if this line closes the fence
			stripped := strings.TrimSpace(line)
			if strings.HasPrefix(stripped, "```") {
				inFence = false
			}
			out[i] = line // return content lines verbatim
		}
	}
	return out
}

