// CommonJS semver library — no dependencies, no package.json

function parseVersion(s) {
  var match = /^(\d+)\.(\d+)\.(\d+)$/.exec(s);
  if (!match) {
    throw new Error('Invalid version format');
  }
  return [parseInt(match[1], 10), parseInt(match[2], 10), parseInt(match[3], 10)];
}

/**
 * Compare two semver version strings: MAJOR.MINOR.PATCH
 * Returns -1, 0, or 1.
 */
function compare(a, b) {
  if (typeof a !== 'string' || typeof b !== 'string') {
    throw new Error('Arguments must be strings');
  }
  var partsA = parseVersion(a.trim());
  var partsB = parseVersion(b.trim());
  for (var i = 0; i < 3; i++) {
    if (partsA[i] < partsB[i]) return -1;
    if (partsA[i] > partsB[i]) return 1;
  }
  return 0;
}

function satisfiesCaret(verParts, rangeStr) {
  var base = parseVersion(rangeStr);
  if (compare(verParts, base) < 0) return false;

  var upper = [base[0], base[1], base[2]];
  if (upper[0] !== 0) {
    upper[0]++; upper[1] = 0; upper[2] = 0;
  } else if (upper[1] !== 0) {
    upper[1]++; upper[2] = 0;
  } else {
    upper[2]++;
  }

  return compare(verParts, upper) < 0;
}

function satisfiesTilde(verParts, rangeStr) {
  var base = parseVersion(rangeStr);
  if (compare(verParts, base) < 0) return false;

  var upper = [base[0], base[1] + 1, 0];
  return compare(verParts, upper) < 0;
}

/**
 * Determine whether a version satisfies a range expression.
 * Returns true or false.
 */
function satisfies(version, range) {
  if (typeof version !== 'string' || typeof range !== 'string') {
    throw new Error('Arguments must be strings');
  }

  var vTrim = version.trim();
  var rTrim = range.trim();
  var verParts = parseVersion(vTrim);

  // "*" matches anything
  if (rTrim === '*') return true;

  // "^X.Y.Z" — caret range
  if (/^\^\d+\.\d+\.\d+$/.test(rTrim)) {
    return satisfiesCaret(verParts, rTrim.substring(1));
  }

  // "~X.Y.Z" — tilde range
  if (/^~\d+\.\d+\.\d+$/.test(rTrim)) {
    return satisfiesTilde(verParts, rTrim.substring(1));
  }

  // ">=X.Y.Z" — greater-or-equal
  var mGte = /^>=(\d+\.\d+\.\d+)$/.exec(rTrim);
  if (mGte) {
    return compare(verParts, mGte[1]) >= 0;
  }

  // ">X.Y.Z" — strictly greater (must not be ">=")
  var mGt = /^>(\d+\.\d+\.\d+)$/.exec(rTrim);
  if (mGt) {
    return compare(verParts, mGt[1]) > 0;
  }

  // "<=X.Y.Z" — less-or-equal
  var mLte = /^<=(\d+\.\d+\.\d+)$/.exec(rTrim);
  if (mLte) {
    return compare(verParts, mLte[1]) <= 0;
  }

  // "<X.Y.Z" — strictly less (must not be "<=")
  var mLt = /^<(\d+\.\d+\.\d+)$/.exec(rTrim);
  if (mLt) {
    return compare(verParts, mLt[1]) < 0;
  }

  // Bare version — equality check
  // validate that the range is itself a valid version (will throw if not)
  parseVersion(rTrim);
  return compare(verParts, rTrim) === 0;
}

module.exports = {
  compare: compare,
  satisfies: satisfies
};

