#!/usr/bin/env node
// Command line front end for semver library

var semver = require('./semver.js');

var args = process.argv.slice(2);

if (args.length < 2) {
  process.stderr.write('Usage: node cli.js <command> <arg1> [arg2]\n');
  process.exit(1);
}

var command = args[0];

try {
  if (command === 'compare') {
    if (args.length !== 3) {
      throw new Error('compare requires exactly two arguments');
    }
    var result = semver.compare(args[1], args[2]);
    process.stdout.write(String(result) + '\n');
  } else if (command === 'satisfies') {
    if (args.length !== 3) {
      throw new Error('satisfies requires exactly two arguments');
    }
    var ok = semver.satisfies(args[1], args[2]);
    process.stdout.write(String(ok) + '\n');
  } else {
    throw new Error('Unknown command: ' + command);
  }
} catch (e) {
  process.stderr.write(e.message + '\n');
  process.exit(1);
}

