// Comprehensive test for semver library
var semver = require('./semver.js');
var passed = 0;
var failed = 0;

function assert(cond, msg) {
  if (cond) { passed++; } else { console.log('FAIL: ' + msg); failed++; }
}

function assertEquals(actual, expected, msg) {
  assert(actual === expected, msg + ' (got ' + actual + ', expected ' + expected + ')');
}

// ===== compare() tests =====
assertEquals(semver.compare('1.0.0', '2.0.0'), -1, 'compare 1 vs 2');
assertEquals(semver.compare('2.0.0', '1.0.0'), 1, 'compare 2 vs 1');
assertEquals(semver.compare('1.2.3', '1.2.3'), 0, 'compare equal');
assertEquals(semver.compare('1.9.0', '1.10.0'), -1, 'compare numeric 9 vs 10');
assertEquals(semver.compare('1.0.1', '1.0.2'), -1, 'compare patch');
assertEquals(semver.compare('0.0.1', '0.0.2'), -1, 'compare zero major/minor');

// Whitespace
assertEquals(semver.compare(' 1.0.0 ', '1.0.0'), 0, 'compare whitespace');

// Invalid inputs should throw
assertThrows(function() { semver.compare('1.2', '1.2.3'); }, 'compare invalid shorter');
assertThrows(function() { semver.compare('1.2.3.4', '1.2.3'); }, 'compare invalid longer');
assertThrows(function() { semver.compare('v1.2.3', '1.2.3'); }, 'compare invalid prefix v');
assertThrows(function() { semver.compare(123, '1.2.3'); }, 'compare non-string arg');

// ===== satisfies() tests - bare version (equality) =====
assert(semver.satisfies('1.2.3', '1.2.3') === true, 'bare: exact match');
assert(semver.satisfies('1.2.3', '1.2.4') === false, 'bare: not equal');
assert(semver.satisfies(' 1.2.3 ', '1.2.3') === true, 'bare: whitespace version');
assert(semver.satisfies('1.2.3', ' 1.2.3 ') === true, 'bare: whitespace range');

// ===== satisfies() tests - wildcard * =====
assert(semver.satisfies('0.0.0', '*') === true, 'wildcard matches 0.0.0');
assert(semver.satisfies('999.999.999', '*') === true, 'wildcard matches high');

// ===== satisfies() tests - caret ^X.Y.Z =====
// ^1.2.3 means >=1.2.3 and <2.0.0
assert(semver.satisfies('1.2.3', '^1.2.3') === true, 'caret 1.2.3 base');
assert(semver.satisfies('1.3.0', '^1.2.3') === true, 'caret 1.3.0');
assert(semver.satisfies('1.9.9', '^1.2.3') === true, 'caret 1.9.9');
assert(semver.satisfies('1.2.2', '^1.2.3') === false, 'caret below base');
assert(semver.satisfies('2.0.0', '^1.2.3') === false, 'caret boundary next major');
assert(semver.satisfies('0.9.9', '^1.2.3') === false, 'caret well below');

// ^0.2.3 means >=0.2.3 and <0.3.0
assert(semver.satisfies('0.2.3', '^0.2.3') === true, 'caret 0.2.3 base');
assert(semver.satisfies('0.2.9', '^0.2.3') === true, 'caret 0.2.x');
assert(semver.satisfies('0.3.0', '^0.2.3') === false, 'caret boundary minor for 0.x');

// ^0.0.3 means >=0.0.3 and <0.0.4
assert(semver.satisfies('0.0.3', '^0.0.3') === true, 'caret 0.0.3 base');
assert(semver.satisfies('0.0.3.5', function() { try { return semver.satisfies('0.0.3.5', '^0.0.3'); } catch(e) { return null; }}()); // invalid version throws

// ===== satisfies() tests - tilde ~X.Y.Z =====
// ~1.2.3 means >=1.2.3 and <1.3.0
assert(semver.satisfies('1.2.3', '~1.2.3') === true, 'tilde 1.2.3 base');
assert(semver.satisfies('1.2.9', '~1.2.3') === true, 'tilde 1.2.x');
assert(semver.satisfies('1.3.0', '~1.2.3') === false, 'tilde boundary');
assert(semver.satisfies('1.2.2', '~1.2.3') === false, 'tilde below base');

// ~0.2.3 means >=0.2.3 and <0.3.0
assert(semver.satisfies('0.2.3', '~0.2.3') === true, 'tilde 0.2.3 base');
assert(semver.satisfies('0.2.9', '~0.2.3') === true, 'tilde 0.2.x');
assert(semver.satisfies('0.3.0', '~0.2.3') === false, 'tilde boundary 0.x');

// ===== satisfies() tests - operators >=, >, <=, < =====
assert(semver.satisfies('1.2.3', '>=1.2.3') === true, 'gte exact');
assert(semver.satisfies('1.2.4', '>=1.2.3') === true, 'gte higher');
assert(semver.satisfies('1.2.2', '>=1.2.3') === false, 'gte lower');

assert(semver.satisfies('1.2.4', '>1.2.3') === true, 'gt higher');
assert(semver.satisfies('1.2.3', '>1.2.3') === false, 'gt exact same');
assert(semver.satisfies('1.2.2', '>1.2.3') === false, 'gt lower');

assert(semver.satisfies('1.2.3', '<=1.2.3') === true, 'lte exact');
assert(semver.satisfies('1.2.2', '<=1.2.3') === true, 'lte lower');
assert(semver.satisfies('1.2.4', '<=1.2.3') === false, 'lte higher');

assert(semver.satisfies('1.2.2', '<1.2.3') === true, 'lt lower');
assert(semver.satisfies('1.2.3', '<1.2.3') === false, 'lt exact same');
assert(semver.satisfies('1.2.4', '<1.2.3') === false, 'lt higher');

// Invalid range should throw
assertThrows(function() { semver.satisfies('1.2.3', 'invalid-range'); }, 'satisfies invalid range');
assertThrows(function() { semver.satisfies('1.2', '^1.2.3'); }, 'satisfies invalid version');
assertThrows(function() { semver.satisfies('1.2.3', '^bad'); }, 'satisfies invalid caret base');
assertThrows(function() { semver.satisfies('1.2.3', '~bad'); }, 'satisfies invalid tilde base');
assertThrows(function() { semver.satisfies('1.2.3', '>=bad'); }, 'satisfies invalid gte');
assertThrows(function() { semver.satisfies(null, '1.2.3'); }, 'satisfies non-string version');
assertThrows(function() { semver.satisfies('1.2.3', null); }, 'satisfies non-string range');

// ===== Output results =====
console.log('\n=== Results ===');
console.log('Passed: ' + passed);
console.log('Failed: ' + failed);
if (failed > 0) process.exitCode = 1;

