'use strict';

/**
 * Parse a version string into [major, minor, patch].
 */
function parseVersion(v) {
  if (typeof v !== 'string') {
    throw new Error('Invalid version: expected a string');
  }
  var trimmed = v.trim();
  var m = /^(\d+)\.(\d+)\.(\d+)$/.exec(trimmed);
  if (!m) {
    throw new Error('Invalid version: "' + trimmed + '" — expected MAJOR.MINOR.PATCH');
  }
  return [Number(m[1]), Number(m[2]), Number(m[3])];
}

/**
 * Compare two versions numerically by each field.
 * Returns -1, 0, or 1.
 */
exports.compare = function compare(a, b) {
  var va = parseVersion(a);
  var vb = parseVersion(b);
  for (var i = 0; i < 3; i++) {
    if (va[i] < vb[i]) return -1;
    if (va[i] > vb[i]) return 1;
  }
  return 0;
};

/**
 * Determine whether *version* satisfies *range*.
 * Range forms: bare version, *, ^X.Y.Z, ~X.Y.Z, >=X.Y.Z, >X.Y.Z, <=X.Y.Z, <X.Y.Z
 */
exports.satisfies = function satisfies(version, range) {
  if (typeof range === 'undefined' || typeof range !== 'string') {
    throw new Error('Invalid range: expected a string');
  }
  var ver = parseVersion(version);

  // strip whitespace from the whole range expression
  range = range.trim();

  // wildcard
  if (range === '*') return true;

  var op, rv;
  var cmpIdx; // where we found a prefix operator so we can split

  // Detect prefix operators: >= > <= < ^ ~
  if (range.charAt(0) === '>') {
    op = range.substring(0, 2); // could be ">=" or ">"
    rv = range.substring(2);
  } else if (range.charAt(0) === '<') {
    op = range.substring(0, 2);
    rv = range.substring(2);
  } else if (range.charAt(0) === '^' || range.charAt(0) === '~') {
    op = range.charAt(0);
    rv = range.substring(1);
  } else {
    // bare version — equality
    op = undefined;
    rv = range;
  }

  var rev = parseVersion(rv); // throws if bad
  var c = exports.compare(version, rv);

  switch (op) {
    case undefined: // bare version
      return c === 0;

    case '>=':
      return c >= 0;

    case '>':
      return c > 0;

    case '<=':
      return c <= 0;

    case '<':
      return c < 0;

    case '^':
      // ^X.Y.Z means >= X.Y.Z AND < next breaking version
      if (c < 0) return false;
      // Find the upper bound: increment the leftmost non-zero field
      if (rev[0] !== 0) {
        // Major is non-zero: upper bound is (rev[0]+1).0.0
        return ver[0] < rev[0] + 1;
      } else if (rev[1] !== 0) {
        // Major is 0, minor is non-zero: upper bound is 0.(rev[1]+1).0
        return ver[1] < rev[1] + 1;
      } else {
        // Major and minor are 0: upper bound is 0.0.(rev[2]+1)
        return ver[2] < rev[2] + 1;
      }

    case '~':
      // ~X.Y.Z means >= X.Y.Z AND < X.(Y+1).0
      if (c < 0) return false;
      if (ver[0] !== rev[0]) return false;
      return ver[1] < rev[1] + 1;

    default:
      throw new Error('Invalid range: "' + range + '"');
  }
};

