#!/usr/bin/env node
'use strict';

var semver = require('./semver');

var args = process.argv.slice(2);

var command = args[0];

if (command === 'compare') {
  if (args.length !== 2) {
    process.stderr.write('Usage: node cli.js compare A B\n');
    process.exit(1);
  }
  try {
    var result = semver.compare(args[1], args[2]);
    process.stdout.write(String(result) + '\n');
  } catch (e) {
    process.stderr.write(e.message + '\n');
    process.exit(1);
  }
} else if (command === 'satisfies') {
  if (args.length !== 2) {
    process.stderr.write('Usage: node cli.js satisfies V RANGE\n');
    process.exit(1);
  }
  try {
    var result = semver.satisfies(args[1], args[2]);
    process.stdout.write((result ? 'true' : 'false') + '\n');
  } catch (e) {
    process.stderr.write(e.message + '\n');
    process.exit(1);
  }
} else {
  process.stderr.write('Unknown command: ' + command + '\n');
  process.stderr.write('Usage: node cli.js compare A B\n');
  process.stderr.write('       node cli.js satisfies V RANGE\n');
  process.exit(1);
}

