  if (value !== true) {
    console.log('FAIL: ' + label);
    process.exit(1);
  }
}

// compare tests
assert('equal', semver.compare('1.0.0', '1.0.0') === 0);
assert('less', semver.compare('1.0.0', '2.0.0') === -1);
assert('greater', semver.compare('2.0.0', '1.0.0') === 1);
assert('minor numeric', semver.compare('1.9.0', '1.10.0') === -1);
assert('major wins', semver.compare('1.99.0', '2.0.0') === -1);
assert('whitespace', semver.compare(' 1.0.0 ', '1.0.0') === 0);

// Invalid inputs throw
try { semver.compare('1.2', '1.0.0'); console.log('FAIL: should throw for 1.2'); process.exit(1); } catch(e) {}
try { semver.compare('1.2.3.4', '1.0.0'); console.log('FAIL: should throw for extra field'); process.exit(1); } catch(e) {}
try { semver.compare('v1.2.3', '1.0.0'); console.log('FAIL: should throw for v prefix'); process.exit(1); } catch(e) {}
