assert('^1.2.3 exact match', semver.satisfies('1.2.3', '^1.2.3'));
assert('^1.2.3 below lower', !semver.satisfies('1.2.2', '^1.2.3'));
assert('^1.2.3 above upper', !semver.satisfies('2.0.0', '^1.2.3'));
assert('^1.2.3 in range', semver.satisfies('1.99.99', '^1.2.3'));
assert('^1.2.3 mid', semver.satisfies('1.3.0', '^1.2.3'));

// ^0.2.3: >= 0.2.3, < 0.3.0
assert('^0.2.3 exact', semver.satisfies('0.2.3', '^0.2.3'));
