assert('^0.2.3 at 0.3.0', !semver.satisfies('0.3.0', '^0.2.3'));
assert('^0.2.3 in range', semver.satisfies('0.2.99', '^0.2.3'));

// ^0.0.3: >= 0.0.3, < 0.0.4
assert('^0.0.3 exact', semver.satisfies('0.0.3', '^0.0.3'));
assert('^0.0.3 below', !semver.satisfies('0.0.2', '^0.0.3'));
assert('^0.0.3 at 0.0.4', !semver.satisfies('0.0.4', '^0.0.3'));
assert('^0.0.3 in range', semver.satisfies('0.0.35', '^0.0.3'));

// ~X.Y.Z: >= X.Y.Z, < X.(Y+1).0
assert('~0.2.3 exact', semver.satisfies('0.2.3', '~0.2.3'));
assert('~0.2.3 below', !semver.satisfies('0.2.2', '~0.2.3'));
assert('~0.2.3 at next minor', !semver.satisfies('0.3.0', '~0.2.3'));
