assert('~0.2.3 major mismatch', !semver.satisfies('1.2.3', '~0.2.3'));

// bare version
assert('exact match', semver.satisfies('1.0.0', '1.0.0'));
assert('no match', !semver.satisfies('1.0.1', '1.0.0'));

// wildcard
assert('*', semver.satisfies('1.0.0', '*'));
assert('* ver2', semver.satisfies('99.99.99', '*'));

// comparison operators
assert('>= 1.0.0 on 1.0.0', semver.satisfies('1.0.0', '>=1.0.0'));
