assert('> 1.0.0 on 1.0.1', semver.satisfies('1.0.1', '>1.0.0'));
assert('> 1.0.0 on 1.0.0', !semver.satisfies('1.0.0', '>1.0.0'));
assert('<= 1.0.0 on 1.0.0', semver.satisfies('1.0.0', '<=1.0.0'));
assert('<= 1.0.0 on 0.9.9', semver.satisfies('0.9.9', '<=1.0.0'));
assert('<= 1.0.0 on 1.0.1', !semver.satisfies('1.0.1', '<=1.0.0'));
assert('< 1.0.0 on 0.9.9', semver.satisfies('0.9.9', '<1.0.0'));
assert('< 1.0.0 on 1.0.0', !semver.satisfies('1.0.0', '<1.0.0'));

// operators with spaces
