assert('spaces >', semver.satisfies('1.0.1', '> 1.0.0'));
assert('spaces <=', semver.satisfies('0.9.9', '<= 1.0.0'));
assert('spaces <', semver.satisfies('0.9.9', '< 1.0.0'));

// invalid version throws
try { semver.satisfies('1.2', '*'); console.log('FAIL: invalid version'); process.exit(1); } catch(e) {}
try { semver.satisfies('1.0.0', '1.2'); console.log('FAIL: invalid range version'); process.exit(1); } catch(e) {}
try { semver.satisfies('1.0.0', 'v1.0.0'); console.log('FAIL: invalid range'); process.exit(1); } catch(e) {}
try { semver.satisfies(null, '1.0.0'); console.log('FAIL: null version'); process.exit(1); } catch(e) {}

console.log('ALL TESTS PASSED');
