'use strict';

/**
 * Compare two semver strings "MAJOR.MINOR.PATCH" (digits only).
 * Returns -1, 0, or 1.  Whitespace around the string is allowed.
 * Throws on any malformed input.
 */
function parse(v) {
  if (typeof v !== 'string') throw new Error('version must be a string');
  v = v.trim();
  var m = /^(\d+)\.(\d+)\.(\d+)$/.exec(v);
  if (!m) throw new Error('invalid version: ' + JSON.stringify(v));
  return [+m[1], +m[2], +m[3]];
}

function compare(a, b) {
  var av = parse(a);
  var bv = parse(b);
  for (var i = 0; i < 3; i++) {
    if (av[i] < bv[i]) return -1;
    if (av[i] > bv[i]) return  1;
  }
  return 0;
}

/**
 * Return true when *version* satisfies *range*.
 * Range forms: *, bare version, ^X.Y.Z, ~X.Y.Z, >=V, >V, <=V, <V.
