/** Parse "MAJOR.MINOR.PATCH" into [major,minor,patch] numbers.
 *  Throws on anything that isn't exactly three dot-separated digit fields. */
function parse(v) {
  if (typeof v !== 'string') throw new Error('invalid version');
  v = v.trim();
  var m = /^(\d+)\.(\d+)\.(\d+)$/.exec(v);
  if (!m) throw new Error('invalid version: ' + JSON.stringify(v));
  return [+m[1], +m[2], +m[3]];
}

/** Return -1 | 0 | 1.  Compares two parsed semver arrays directly. */
function _cmp(a, b) {
  for (var i = 0; i < 3; i++) {
    if (a[i] < b[i]) return -1;
    if (a[i] > b[i]) return  1;
  }
  return 0;
}

/** Compare two semver strings; returns -1, 0 or 1. */
function compare(a, b) {
  return _cmp(parse(a), parse(b));
}

/* ------------------------------------------------------------------ */

function _nextBreaking(rv) {
  var v = rv.slice(0); // copy
  for (var i = 0; i < 3; i++) {
    if (v[i] !== 0) {
      v[i]++;
      v[i + 1] = 0;
      v[i + 2] = 0;
      break;
    }
  }
  // ^0.0.0 -> all zeros, loop never fires; next is 0.1.0
  if (v[0] === 0 && v[1] === 0 && v[2] === 0) v[1] = 1;
  return v;
}

function satisfies(version, range) {
  var cv = parse(version);       // throws if bad version

  if (typeof range !== 'string') throw new Error('range must be a string');
  range = range.trim();

