  var verStr = range;

  if (range.charCodeAt(0) === 94) {   // '^'
    op = '^';   verStr = range.slice(1);
  } else if (range.charCodeAt(0) === 126) {  // '~'
    op = '~';   verStr = range.slice(1);
  } else if (range.charCodeAt(0) === 60 && range.charCodeAt(1) === 61) {  // '<='
    op = '<='; verStr = range.slice(2);
  } else if (range.charCodeAt(0) === 62 && range.charCodeAt(1) === 61) {  // '>='
    op = '>='; verStr = range.slice(2);
  } else if (range.charCodeAt(0) === 62) {  // '>'
    op = '>';   verStr = range.slice(1);
  } else if (range.charCodeAt(0) === 60) {  // '<'
    op = '<';   verStr = range.slice(1);
  }

  var rv = parse(verStr);       // throws if range version is invalid

  if (op === '^') {
