'use strict';

var semver = require('./semver');

var args = process.argv.slice(2);

if (args.length < 1) { printUsage(); process.exit(1); }

var cmd = args[0];

try {
  if (cmd === 'compare') {
    if (args.length !== 3) throw new Error('compare requires exactly two version arguments');
    var r = semver.compare(args[1], args[2]);
    process.stdout.write(String(r) + '\n');
  } else if (cmd === 'satisfies') {
    if (args.length !== 3) throw new Error('satisfies requires a version and a range argument');
    var ok = semver.satisfies(args[1], args[2]);
    process.stdout.write(ok ? 'true\n' : 'false\n');
  } else {
    throw new Error('unknown command: ' + cmd);
  }
} catch (err) {
  process.stderr.write(err.message + '\n');
  process.exit(1);
}

