var s = require('./semver');

// Compare tests
console.log('=== compare ===');
console.log(s.compare('1.9.0','1.10.0')); // -1
console.log(s.compare(' 1.2.3 ','1.2.3')); // 0

// Invalid inputs must throw
var errors = [
  () => s.compare('1.2'),
  () => s.compare('1.2.3.4'),
  () => s.compare('v1.2.3'),
  () => s.compare(123, '1.2.3'),
  () => s.satisfies('1.2', '^1.2.3'),
];
errors.forEach(function(fn) { try { fn(); console.log('FAIL no throw'); } catch(e) { console.log('OK throw'); } });

// satisfies bare version
console.log('=== satisfies ===');
console.log(s.satisfies('1.2.3','1.2.3')); // true
console.log(s.satisfies('1.2.4','1.2.3')); // false

// ^ boundary tests
console.log(s.satisfies('2.0.0','^1.2.3'));  // false
console.log(s.satisfies('1.99.99','^1.2.3')); // true
console.log(s.satisfies('0.3.0','^0.2.3'));   // false (boundary)
console.log(s.satisfies('0.2.3','^0.2.3'));   // true (exact match allowed)
console.log(s.satisfies('0.0.4','^0.0.3'));   // false (boundary)
console.log(s.satisfies('0.0.3','^0.0.3'));   // true

// ~ boundary tests
console.log(s.satisfies('1.1.0','~1.0.3'));   // false
console.log(s.satisfies('1.0.9','~1.0.3'));   // true
console.log(s.satisfies('1.0.3','~1.0.3'));   // true (exact match)
console.log(s.satisfies('1.0.2','~1.0.3'));   // false (below min)

// relational operators
console.log(s.satisfies('1.5.0','>1.2.3'));   // true
console.log(s.satisfies('1.2.4','>1.2.3'));   // true
console.log(s.satisfies('1.2.3','>1.2.3'));   // false (not strict)
console.log(s.satisfies('1.5.0','<1.8.0'));   // true
console.log(s.satisfies('1.8.0','<1.8.0'));   // false
console.log(s.satisfies('1.5.0','<=1.5.0'));  // true

// unknown range form must throw
try { s.satisfies('1.0.0','foo bar'); console.log('FAIL'); } catch(e) { console.log('OK invalid range throws'); }
try { s.satisfies('1.0.0','>=1.2'); console.log('FAIL'); } catch(e) { console.log('OK bad version in >= throws'); }

// unknown command on CLI should fail
console.log('ALL DONE');
"

